import http.server, socketserver, sys, json, threading
class H(http.server.BaseHTTPRequestHandler):
    def log_message(self,*a): pass
    def do_GET(self): self.handle_all()
    def do_POST(self): self.handle_all()
    def do_PUT(self): self.handle_all()
    def do_DELETE(self): self.handle_all()
    def do_PATCH(self): self.handle_all()
    def do_HEAD(self): self.handle_all()
    def do_OPTIONS(self): self.handle_all()
    def handle_all(self):
        length=int(self.headers.get('Content-Length',0) or 0)
        body=self.rfile.read(length) if length else b''
        # record
        rec={"method":self.command,"path":self.path,"headers":list(self.headers.items()),"body":body.decode('utf-8', 'surrogateescape')}
        with open('/tmp/last.json','w') as f: json.dump(rec,f)
        if self.path.startswith('/json'):
            data=b'{"a":1,"b":[2,3]}'
            self.send_response(200); self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(data))); self.send_header('X-Custom','hi'); self.end_headers(); self.wfile.write(data); return
        if self.path.startswith('/status/'):
            code=int(self.path.split('/')[2] or 200)
            data=f"status {code}".encode()
            self.send_response(code); self.send_header('Content-Type','text/plain'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if self.path.startswith('/redirect'):
            # /redirect/N or /redirect?to=
            self.send_response(302); self.send_header('Location','/json'); self.send_header('Content-Length','0'); self.end_headers(); return
        if self.path.startswith('/redirect-loop'):
            self.send_response(302); self.send_header('Location','/redirect-loop'); self.send_header('Content-Length','0'); self.end_headers(); return
        if self.path.startswith('/headersorder'):
            data=b'ok'
            self.send_response(200); self.send_header('Z-Last','1'); self.send_header('A-First','2'); self.send_header('Content-Type','text/plain'); self.send_header('Content-Length','2'); self.end_headers(); self.wfile.write(data); return
        if self.path.startswith('/html'):
            data=b'<html><body>hi</body></html>'
            self.send_response(200); self.send_header('Content-Type','text/html'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if self.path.startswith('/xml'):
            data=b'<root><a>1</a></root>'
            self.send_response(200); self.send_header('Content-Type','application/xml'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if self.path.startswith('/gzip'):
            import gzip
            data=gzip.compress(b'gzipped text')
            self.send_response(200); self.send_header('Content-Type','text/plain'); self.send_header('Content-Encoding','gzip'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if self.path.startswith('/deflate'):
            import zlib
            data=zlib.compress(b'deflated text')
            self.send_response(200); self.send_header('Content-Type','text/plain'); self.send_header('Content-Encoding','deflate'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if self.path.startswith('/binary'):
            data=bytes(range(256))
            self.send_response(200); self.send_header('Content-Type','application/octet-stream'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if self.path.startswith('/cookie'):
            data=b'ok'
            self.send_response(200); self.send_header('Set-Cookie','foo=bar; Path=/'); self.send_header('Set-Cookie','baz=qux; Path=/'); self.send_header('Content-Length','2'); self.end_headers(); self.wfile.write(data); return
        if self.path.startswith('/digest'):
            auth=self.headers.get('Authorization','')
            if auth.startswith('Digest'):
                data=b'digest ok'; self.send_response(200); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
            else:
                self.send_response(401); self.send_header('WWW-Authenticate','Digest realm="test", nonce="abc123", qop="auth", algorithm="MD5", opaque="xyz"'); self.send_header('Content-Length','0'); self.end_headers(); return
        if self.path.startswith('/echo'):
            data=json.dumps(rec).encode()
            self.send_response(200); self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if self.path.startswith('/disposition'):
            data=b'filedata'
            self.send_response(200); self.send_header('Content-Disposition','attachment; filename="hello.txt"'); self.send_header('Content-Type','text/plain'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if self.path.startswith('/range'):
            full=b'0123456789abcdef'
            rng=self.headers.get('Range','')
            if rng.startswith('bytes='):
                start=int(rng.split('=')[1].split('-')[0])
                data=full[start:]
                self.send_response(206); self.send_header('Content-Range',f'bytes {start}-{len(full)-1}/{len(full)}'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
            self.send_response(200); self.send_header('Content-Length',str(len(full))); self.send_header('Accept-Ranges','bytes'); self.end_headers(); self.wfile.write(full); return
        # default plain
        data=b'hello world'
        self.send_response(200); self.send_header('Content-Type','text/plain'); self.send_header('Content-Length',str(len(data))); self.end_headers(); 
        if self.command!='HEAD': self.wfile.write(data)
        return
socketserver.TCPServer.allow_reuse_address=True
srv=socketserver.TCPServer(('127.0.0.1',8765), H)
print("serving", flush=True)
srv.serve_forever()
