        parsed=urllib.parse.urlparse(self.path); path=parsed.path; qs=urllib.parse.parse_qs(parsed.query)
        if path=='/json':
            self.send_body(200,b'{"a":1,"b":[2,3]}',[('X-Custom','hi')],'application/json'); return
        if path.startswith('/status/'):
            code=int(path.split('/')[2]); self.send_body(code,f"status {code}"); return
        if path=='/redirect-loop':
            self.send_body(302,b'',[('Location','/redirect-loop')],None); return
        if path=='/redirect-chain':
            n=int(qs.get('n',['0'])[0])
            if n>0: self.send_body(302,b'',[('Location',f'/redirect-chain?n={n-1}')],None)
            else: self.send_body(200,b'done')
            return
        if path.startswith('/redirect'):
            # query params code,to,method?
            code=int(qs.get('code',['302'])[0]); to=qs.get('to',['/json'])[0]
            hs=[('Location',to)]
            if 'cookie' in qs: hs.append(('Set-Cookie',qs['cookie'][0]))
            self.send_body(code,b'redirecting',hs); return
        if path=='/headersorder': self.send_body(200,b'ok',[('Z-Last','1'),('A-First','2')]); return
        if path=='/html': self.send_body(200,b'<html><body><p>hi</p></body></html>',None,'text/html'); return
        if path=='/xml': self.send_body(200,b'<root><a>1</a><b x="y">2</b></root>',None,'application/xml'); return
        if path=='/js': self.send_body(200,b'function x(a){return a+1;}//c\nconst s="hi";',None,'application/javascript'); return
        if path=='/css': self.send_body(200,b'body { color: red; }',None,'text/css'); return
        if path=='/gzip':
            data=gzip.compress(b'gzipped text'); self.send_response(200); self.send_header('Content-Type','text/plain'); self.send_header('Content-Encoding','gzip'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if path=='/deflate':
            data=zlib.compress(b'deflated text'); self.send_response(200); self.send_header('Content-Type','text/plain'); self.send_header('Content-Encoding','deflate'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if path=='/brotli':
            try:
                import brotli; data=brotli.compress(b'brotli text')
            except Exception as e: data=b'no brotli'
            self.send_response(200); self.send_header('Content-Type','text/plain'); self.send_header('Content-Encoding','br'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if path=='/zstd':
            # Use simple pre made? Try import zstandard
            try:
                import zstandard; data=zstandard.ZstdCompressor().compress(b'zstd text')
            except Exception: data=b'no zstd'
            self.send_response(200); self.send_header('Content-Type','text/plain'); self.send_header('Content-Encoding','zstd'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if path=='/binary': self.send_body(200,bytes(range(256)),None,'application/octet-stream'); return
        if path=='/cookie':
            hs=[('Set-Cookie',c) for c in qs.get('c',['foo=bar; Path=/'])]
            self.send_body(200,b'ok',hs); return
        if path=='/digest':
            auth=self.headers.get('Authorization','')
            if auth.startswith('Digest'):
                self.send_body(200,'digest ok '+auth); return
            self.send_body(401,b'auth needed',[('WWW-Authenticate', qs.get('challenge',['Digest realm="test", nonce="abc123", qop="auth", algorithm="MD5", opaque="xyz"'])[0])]); return
        if path=='/basic-auth':
            auth=self.headers.get('Authorization','')
            if auth: self.send_body(200,'auth:'+auth); return
            self.send_body(401,b'auth needed',[('WWW-Authenticate','Basic realm="x"')]); return
        if path=='/echo':
            self.send_body(200,json.dumps(rec),None,'application/json'); return
        if path=='/disposition':
            fn=qs.get('filename',['hello.txt'])[0]; self.send_body(200,b'filedata',[('Content-Disposition',f'attachment; filename="{fn}"')]); return
        if path=='/range':
            full=b'0123456789abcdef'; rng=self.headers.get('Range','')
            if rng.startswith('bytes='):
                start=int(rng.split('=')[1].split('-')[0]); data=full[start:]
                self.send_body(206,data,[('Content-Range',f'bytes {start}-{len(full)-1}/{len(full)}'),('Accept-Ranges','bytes')]); return
            self.send_body(200,full,[('Accept-Ranges','bytes')]); return
        if path=='/slow':
            import time; time.sleep(float(qs.get('t',['1'])[0])); self.send_body(200,b'slow'); return
        if path=='/chunked':
            self.send_response(200); self.send_header('Content-Type','text/plain'); self.send_header('Transfer-Encoding','chunked'); self.end_headers(); self.wfile.write(b'5\r\nhello\r\n6\r\n world\r\n0\r\n\r\n'); return
        if path=='/charset/latin1':
            self.send_body(200,'café'.encode('latin-1'),None,'text/plain; charset=iso-8859-1'); return
        if path=='/charset/utf8-noparam':
            self.send_body(200,'café'.encode('utf-8'),None,'text/plain'); return
        if path=='/empty': self.send_body(200,b''); return
        if path=='/204': self.send_body(204,b''); return
        if path=='/json-large':
            self.send_body(200,json.dumps({"z":1,"a":{"nested":[True,None,1.5,"s"]}}),None,'application/json'); return
        if path=='/json-invalid':
            self.send_body(200,b'{not json}',None,'application/json'); return
        self.send_body(200,b'hello world')
socketserver.ThreadingTCPServer.allow_reuse_address=True
socketserver.ThreadingTCPServer.daemon_threads=True
srv=socketserver.ThreadingTCPServer(('127.0.0.1',8765), H)
print("serving2",flush=True)
srv.serve_forever()
