# ---------- small utilities ----------

def rust_os_error(e):
    err = getattr(e, 'errno', None)
    msg = getattr(e, 'strerror', None) or str(e)
    if msg:
        msg = msg[0].upper() + msg[1:]
    if err is not None:
        return f"{msg} (os error {err})"
    return msg

class XhError(Exception):
    """Runtime error printed as `{bin}: error: ...` with exit 1 (or given)."""
    def __init__(self, msg, exit_code=1, caused_by=None, stderr_text=None):
        super().__init__(msg)
        self.msg = msg
        self.exit_code = exit_code
        self.caused_by = caused_by  # list[str]
        self.stderr_text = stderr_text

class ClapError(Exception):
    def __init__(self, text):
        super().__init__(text)
