def write_stdout_bytes(b):
    if not b:
        return
    try:
        mv = memoryview(b)
        while mv:
            n = os.write(1, mv)
            mv = mv[n:]
    except BrokenPipeError:
        raise
    except OSError:
        # Fallback
        sys.stdout.buffer.write(b); sys.stdout.buffer.flush()

