class JsonFloat(float): pass

class JsonError(Exception):
    def __init__(self, basic, line, col):
        self.basic=basic; self.line=line; self.col=col
        super().__init__(f"{basic} at line {line} column {col}")
    def __str__(self):
        return f"{self.basic} at line {self.line} column {self.col}"

def format_float(v):
    if math.isnan(v) or math.isinf(v):
        return "null"
    if v == 0.0:
        return "-0.0" if math.copysign(1.0, v) < 0 else "0.0"
    r = repr(float(v))
    if 'e' in r or 'E' in r:
        mant, exp = re.split('[eE]', r)
        exp_i = int(exp)
        return f"{mant}e{exp_i}"
    return r

def json_escape_str(s):
    out=['"']
    for ch in s:
        o=ord(ch)
        if ch=='"': out.append('\\"')
        elif ch=='\\': out.append('\\\\')
        elif ch=='\n': out.append('\\n')
        elif ch=='\r': out.append('\\r')
        elif ch=='\t': out.append('\\t')
        elif ch=='\b': out.append('\\b')
        elif ch=='\f': out.append('\\f')
        elif o < 0x20: out.append(f'\\u{o:04x}')
        else: out.append(ch)
    out.append('"')
    return ''.join(out)

def json_dumps_compact(obj):
    if obj is None: return "null"
    if obj is True: return "true"
    if obj is False: return "false"
    if isinstance(obj, JsonFloat): return format_float(obj)
    if isinstance(obj, int): return str(obj)
    if isinstance(obj, float): return format_float(obj)
    if isinstance(obj, str): return json_escape_str(obj)
    if isinstance(obj, (list,tuple)): return '['+','.join(json_dumps_compact(x) for x in obj)+']'
    if isinstance(obj, dict): return '{'+','.join(json_escape_str(str(k))+':'+json_dumps_compact(v) for k,v in obj.items())+'}'
    return json_escape_str(str(obj))

def json_dumps_pretty(obj, indent=4):
    if indent is None: indent=4
    pad_unit=' ' * int(indent)
    def rec(o, lvl):
        if isinstance(o, dict):
            if not o: return '{}'
            inner = pad_unit*(lvl+1); outer=pad_unit*lvl
            parts=[inner + json_escape_str(str(k))+': '+rec(v,lvl+1) for k,v in o.items()]
            return '{\n'+',\n'.join(parts)+'\n'+outer+'}'
        if isinstance(o,(list,tuple)):
            if not o: return '[]'
            inner=pad_unit*(lvl+1); outer=pad_unit*lvl
            parts=[inner+rec(v,lvl+1) for v in o]
            return '[\n'+',\n'.join(parts)+'\n'+outer+']'
        return json_dumps_compact(o)
    return rec(obj,0)

class _JsonParser:
    def __init__(self,text):
