        upto=self.s[:idx]
        line=upto.count('\n')+1
        last=upto.rfind('\n')
        col=(idx-last-1) if eof else (idx-last)
        # serde EOF col = chars in line (0-based count), err col = 1-based
        if eof:
            col=idx-last-1
        else:
            col=idx-last
        return line,col
    def err(self,basic,eof=False,idx=None):
        line,col=self.pos(eof,idx); raise JsonError(basic,line,col)
    def skip(self):
        while self.i<self.n and self.s[self.i] in ' \t\n\r': self.i+=1
