        if c=='[': return self.arr()
        if c=='"': return self.string()
        if c=='t': return self.lit('true',True)
        if c=='f': return self.lit('false',False)
        if c=='n': return self.lit('null',None)
        if c=='-' or c.isdigit(): return self.number()
        self.err('expected value')
    def lit(self,word,val):
        if self.s.startswith(word,self.i):
            self.i+=len(word); return val
        self.err('expected value')
    def number(self):
        start=self.i
        if self.i<self.n and self.s[self.i]=='-': self.i+=1
        if self.i>=self.n or not self.s[self.i].isdigit():
            self.err('invalid number', idx=self.i if self.i<self.n else self.i)
        if self.s[self.i]=='0':
            self.i+=1
            if self.i<self.n and self.s[self.i].isdigit(): self.err('invalid number')
        else:
            while self.i<self.n and self.s[self.i].isdigit(): self.i+=1
        is_float=False
        if self.i<self.n and self.s[self.i]=='.':
            is_float=True; self.i+=1
            if self.i>=self.n or not self.s[self.i].isdigit(): self.err('invalid number')
            while self.i<self.n and self.s[self.i].isdigit(): self.i+=1
        if self.i<self.n and self.s[self.i] in 'eE':
            is_float=True; self.i+=1
            if self.i<self.n and self.s[self.i] in '+-': self.i+=1
            if self.i>=self.n or not self.s[self.i].isdigit(): self.err('invalid number')
            while self.i<self.n and self.s[self.i].isdigit(): self.i+=1
        tok=self.s[start:self.i]
        if is_float or tok=='-0':
            try: f=float(tok)
            except Exception: self.err('number out of range',eof=True,idx=self.i)
            if math.isinf(f):
                line,col=self.pos(eof=True,idx=self.i); raise JsonError('number out of range',line,col)
            return JsonFloat(f)
        try: iv=int(tok)
        except Exception: return JsonFloat(float(tok))
        # serde_json: fits in i64/u64 as int, else float
        if tok.startswith('-'):
            if iv < -(1<<63): return JsonFloat(float(tok))
        else:
            if iv > (1<<64)-1: return JsonFloat(float(tok))
