        while True:
            if self.i>=self.n: self.err('EOF while parsing a string',eof=True)
            c=self.s[self.i]
            if c=='"': self.i+=1; return ''.join(out)
            if c=='\\':
                self.i+=1
                if self.i>=self.n: self.err('EOF while parsing a string',eof=True)
                e=self.s[self.i]; self.i+=1
                mp={'"':'"','\\':'\\','/':'/','b':'\b','f':'\f','n':'\n','r':'\r','t':'\t'}
                if e in mp: out.append(mp[e])
                elif e=='u':
                    if self.i+4>self.n: self.err('EOF while parsing a string',eof=True,idx=self.n)
                    hexd=self.s[self.i:self.i+4]
                    if not re.fullmatch(r'[0-9a-fA-F]{4}',hexd): self.err('invalid escape')
                    code=int(hexd,16); self.i+=4
                    if 0xD800 <= code <= 0xDBFF and self.s[self.i:self.i+2]=='\\u':
                        hex2=self.s[self.i+2:self.i+6]
                        if re.fullmatch(r'[0-9a-fA-F]{4}',hex2 or ''):
                            code2=int(hex2,16)
                            if 0xDC00 <= code2 <= 0xDFFF:
                                self.i+=6; out.append(chr(0x10000+((code-0xD800)<<10)+(code2-0xDC00))); continue
                    out.append(chr(code))
                else: self.err('invalid escape', idx=self.i-1)
                continue
            if ord(c)<0x20: self.err('control character (\\u0000-\\u001F) found while parsing a string')
            out.append(c); self.i+=1
    def arr(self):
        self.i+=1; out=[]; self.skip()
        if self.i<self.n and self.s[self.i]==']': self.i+=1; return out
        while True:
            out.append(self.value()); self.skip()
            if self.i>=self.n: self.err('EOF while parsing a list',eof=True)
            c=self.s[self.i]
            if c==']': self.i+=1; return out
            if c!=',': self.err('expected `,` or `]`')
            self.i+=1; self.skip()
            if self.i<self.n and self.s[self.i]==']': self.err('trailing comma')
    def obj(self):
        self.i+=1; out={}; self.skip()
        if self.i<self.n and self.s[self.i]=='}': self.i+=1; return out
        while True:
            self.skip()
            if self.i>=self.n: self.err('EOF while parsing an object',eof=True)
            if self.s[self.i]!='"': self.err('key must be a string')
            k=self.string(); self.skip()
            if self.i>=self.n: self.err('EOF while parsing an object',eof=True)
            if self.s[self.i]!=':': self.err('expected `:`')
            self.i+=1; out[k]=self.value(); self.skip()
            if self.i>=self.n: self.err('EOF while parsing an object',eof=True)
            c=self.s[self.i]
            if c=='}': self.i+=1; return out
            if c!=',': self.err('expected `,` or `}`')
            self.i+=1; self.skip()
            if self.i<self.n and self.s[self.i]=='}': self.err('trailing comma')

def json_parse(text):
    return _JsonParser(text).parse()

