        candidate=f'{default_scheme}{raw}' if not default_scheme.endswith(':') else f'{default_scheme}{raw[1:]}'
    elif raw.startswith(':'):
        candidate=f'{default_scheme}://localhost{raw}'
    elif re.search(r'[A-Za-z0-9]://.+', raw, flags=re.DOTALL):
        candidate=raw
    else:
        candidate=f'{default_scheme}://{raw}'
    return parse_url_candidate(candidate)

