    def __init__(self):
        self.entries=[]  # list of [lowername, [bytes,...]]
    def _find(self,name):
        name=name.lower()
        for i,e in enumerate(self.entries):
            if e[0]==name: return i
        return -1
    def insert(self,name,value_b):
        if isinstance(value_b,str): value_b=value_b.encode('utf-8','surrogateescape')
        i=self._find(name)
        if i>=0: self.entries[i][1]=[value_b]
        else: self.entries.append([name.lower(),[value_b]])
    def append(self,name,value_b):
        if isinstance(value_b,str): value_b=value_b.encode('utf-8','surrogateescape')
        i=self._find(name)
        if i>=0: self.entries[i][1].append(value_b)
        else: self.entries.append([name.lower(),[value_b]])
    def remove(self,name):
        i=self._find(name)
        if i<0: return
        if i==len(self.entries)-1:
            self.entries.pop()
        else:
            last=self.entries.pop()
            self.entries[i]=last
    def get_all(self,name):
        i=self._find(name)
