        self.msg=msg; self.key=key; self.pos=pos; self.span=span
        super().__init__(msg)
    def render(self, binstem):
        key=self.key
        disp=key if self.pos < len(key) else key+' '
        if key=='' : disp=' '
        # pos can be >len? ensure spaces
        caret_line='  ' + (' '*self.pos) + ('^'*max(1,self.span))
        return f"{binstem}: error: {self.msg}\n\n  {disp}\n{caret_line}\n"

@dataclass
class PathToken:
    kind: str  # key,index,append
    value: object=None
    start: int=0
    end: int=0  # exclusive raw end

def _rust_usize(s):
    if not re.fullmatch(r'\+?[0-9]+',s or ''): return None
    try: v=int(s,10)
    except: return None
    if v>(1<<64)-1: return None
    return v

def parse_json_path(raw):
    # returns list tokens; raise PathError
    L=len(raw); i=0; tokens=[]
    if L==0:
        raise PathError("expected text or '['",raw,0,1)

    def parse_bracket(i, root=False):
        # i at '['; returns (token, next_i)
        start=i; i+=1
        if i>=L:
            if root: raise PathError("expected number or ']'",raw,i,1)
            raise PathError("expected text, number or ']'",raw,i,1)
        if raw[i]==']':
            return PathToken('append',None,start,i+1), i+1
        if raw[i]=='[':
            if root: raise PathError("expected number or ']'",raw,i,1)
            raise PathError("expected text, number or ']'",raw,i,1)
        tok_start=i; out=[]
        while i<L:
            c=raw[i]
            if c=='\\' and i+1<L and raw[i+1] in ESCAPABLE_KEY:
                out.append(raw[i+1]); i+=2; continue
            if c in '[]':
                break
            out.append(c); i+=1
        text=''.join(out)
        if i>=L:
            raise PathError("expected ']'",raw,i,1)
        if raw[i]!=' ]'.replace(' ',''):
            # next char is '['
            raise PathError("expected ']'",raw,i,1)
        if raw[i]!=']':
            raise PathError("expected ']'",raw,i,1)
        i+=1
        if root:
            idx=_rust_usize(text)
            if idx is None:
                raise PathError("expected number or ']'",raw,tok_start,1)
            return PathToken('index',idx,start,i), i
        idx=_rust_usize(text)
        if idx is not None:
            return PathToken('index',idx,start,i), i
        return PathToken('key',text,start,i), i

    if raw[0]=='[':
        tok,i=parse_bracket(0,root=True); tokens.append(tok)
    else:
        if raw[0]==']':
            raise PathError("expected text or '['",raw,0,1)
        start=0; out=[]
        while i<L:
            c=raw[i]
            if c=='\\' and i+1<L and raw[i+1] in ESCAPABLE_KEY:
                out.append(raw[i+1]); i+=2; continue
            if c in '[]': break
            out.append(c); i+=1
        text=''.join(out)
        if text=='':
            raise PathError("expected text or '['",raw,0,1)
        tokens.append(PathToken('key',text,start,i))
    while i<L:
        if raw[i]!='[':
            raise PathError("expected '['",raw,i,1)
        tok,i=parse_bracket(i,root=False); tokens.append(tok)
    return tokens

def _json_type(v):
    if v is None: return 'null'
    if isinstance(v,bool): return 'bool'
    if isinstance(v,str): return 'string'
    if isinstance(v,(int,float,JsonFloat)): return 'number'
    if isinstance(v,list): return 'array'
    if isinstance(v,dict): return 'object'
    return 'null'

def apply_json_path(root_holder, raw, value):
    # root_holder is list [root] where 'NONE_SENTINEL' object means unset
    tokens=parse_json_path(raw)
    UNSET=root_holder[1]
    # Traverse
    def access_error(tok, prefix_raw, cur):
        need='object' if tok.kind=='key' else 'array'
        op=tok.kind
        msg=f"Can't perform '{op}' based access on '{prefix_raw}' which has a type of '{_json_type(cur)}' but this operation requires a type of '{need}'."
        raise PathError(msg,raw,tok.start,max(1,tok.end-tok.start))
    # recursive iterative with parent refs: represent location via function get/set
    # Build list of containers along the way.
    # We maintain a list 'chain' of objects/values and how to assign a child back.
    # Simpler recursive:
    def rec(cur, idx):
        tok=tokens[idx]
        last = idx==len(tokens)-1
        prefix_raw=raw[:tok.start]
        if tok.kind=='key':
            if cur is UNSET: cur={}
            elif not isinstance(cur,dict): access_error(tok,prefix_raw,cur)
            if last:
                cur[tok.value]=value
            else:
                child=cur.get(tok.value, UNSET)
                cur[tok.value]=rec(child, idx+1)
            return cur
        elif tok.kind=='index':
            if cur is UNSET: cur=[]
            elif not isinstance(cur,list): access_error(tok,prefix_raw,cur)
            while len(cur)<=tok.value: cur.append(None)
            if last:
                cur[tok.value]=value
            else:
                child=cur[tok.value]
                # If slot is padding null created just now? Existing null must error.
                # rec will treat None as a value (null), not UNSET, causing error for deeper access - unless we just created the slot in this op without prior existence.
                # Distinguish: if index was >= original len before fill, child should be UNSET.
                # Our loop already padded; recompute: (handled by caller? To preserve semantics of a[2][b] creating idx2 object, nested fresh slot should be unset not null.)
                # We detect: if we padded beyond, child considered UNSET when slot was newly created. We don't have original len stored - patch: record before padding above.
                cur[tok.value]=rec(child, idx+1)
            return cur
        else: # append
            if cur is UNSET: cur=[]
            elif not isinstance(cur,list): access_error(tok,prefix_raw,cur)
            if last:
                cur.append(value)
            else:
                child=rec(UNSET, idx+1); cur.append(child)
            return cur

    # Monkey-patch rec index fresh handling: wrap recursive with custom implementation
    def rec2(cur, idx, fresh=False):
        tok=tokens[idx]; last=idx==len(tokens)-1; prefix_raw=raw[:tok.start]
        if tok.kind=='key':
            if cur is UNSET: cur={}
            elif not isinstance(cur,dict): access_error(tok,prefix_raw,cur)
            if last: cur[tok.value]=value
            else:
                child=cur.get(tok.value, UNSET)
                cur[tok.value]=rec2(child, idx+1)
            return cur
        if tok.kind=='index':
            if cur is UNSET: cur=[]
            elif not isinstance(cur,list): access_error(tok,prefix_raw,cur)
            orig_len=len(cur)
            while len(cur)<=tok.value: cur.append(None)
            if last: cur[tok.value]=value
            else:
                child=UNSET if tok.value>=orig_len else cur[tok.value]
                cur[tok.value]=rec2(child, idx+1)
            return cur
        # append
        if cur is UNSET: cur=[]
        elif not isinstance(cur,list): access_error(tok,prefix_raw,cur)
        if last: cur.append(value)
        else: cur.append(rec2(UNSET, idx+1))
        return cur
    root_holder[0]=rec2(root_holder[0],0)
    return root_holder[0]

