def prompt_password(scheme, username, host):
    prompt=f"{scheme}: password for {username}@{host}: "
    # rpassword: opens /dev/tty for input/output; prompt printed there.
    try:
        tty_in=open('/dev/tty','rb',buffering=0)
    except OSError as e:
        raise XhError(rust_os_error(e))
    try:
        try: tty_out=open('/dev/tty','wb',buffering=0)
        except: tty_out=None
        if tty_out: tty_out.write(prompt.encode())
        else: sys.stdout.write(prompt); sys.stdout.flush()
        # disable echo if possible
        old=None
        fd=tty_in.fileno()
        try:
            import termios
            old=termios.tcgetattr(fd)
            new=list(old); new[3] &= ~termios.ECHO
            termios.tcsetattr(fd,termios.TCSADRAIN,new)
        except Exception: old=None
        try:
            line=b''
            while True:
                chunk=tty_in.read(1)
                if not chunk: break
                if chunk in (b'\n',b'\r'): break
                if chunk==b'\x03': raise KeyboardInterrupt()
                line+=chunk
        finally:
            if old is not None:
                try:
                    import termios; termios.tcsetattr(fd,termios.TCSADRAIN,old)
                except Exception: pass
            if tty_out: tty_out.write(b'\n')
        return line.decode('utf-8','surrogateescape')
    finally:
        try: tty_in.close()
        except: pass

def parse_auth_raw(raw, kind, url):
    # kind bearer: token=raw
    if kind=='bearer':
        return Auth(kind='bearer',token=raw,raw=raw)
    # split user:pass requiring user at least 1 char before first colon? observed :pass treated as username.
    m=re.match(r'^(.+?):(.*)$', raw, flags=re.DOTALL)
    if m:
        return Auth(kind=kind,username=m.group(1),password=m.group(2),raw=raw)
    # If raw is ':' alone, regex requires .+ before colon fails? But earlier ':' gave Basic ':' without prompt. Special: raw == ':' -> user='', pass=''
    if raw==':':
        return Auth(kind=kind,username='',password='',raw=raw)
    # prompt
    pw=prompt_password(url.scheme, raw, url.host_connect or url.host or '')
    raw2=f"{raw}:{pw}"
    return Auth(kind=kind,username=raw,password=pw,raw=raw2)

