    if 'NETRC' in os.environ:
        p=Path(os.environ['NETRC'])
        return p if p.exists() else None
    home=os.environ.get('HOME')
    if not home: return None
    for name in ('.netrc','_netrc'):
        p=Path(home)/name
        if p.exists(): return p
    return None

def parse_netrc(path):
    try: text=path.read_text(encoding='utf-8',errors='surrogateescape')
    except: return {}
    # strip comments lines starting with # after optional whitespace, and inline comments? observed worked; handle # at token start to EOL
    entries={}; default=None
    # Tokenize line aware for macdef
    lines=text.splitlines()
    i=0; cur=None; curkey=None
    def finish():
        nonlocal cur,curkey,default
        if cur is not None:
            if curkey=='default': default=cur
            elif curkey: entries.setdefault(curkey.lower(),cur)
        cur=None; curkey=None
    # Flatten tokens with line logic for macdef
    idx=0
    tokens=[]  # not used
    while idx<len(lines):
        line=lines[idx]; idx+=1
        stripped=line.strip()
        if stripped.startswith('#'): continue
        # remove inline comment starting with # as token
        parts=[]
        for tok in stripped.split():
            if tok.startswith('#'): break
            parts.append(tok)
        j=0
        while j<len(parts):
            tok=parts[j]
            if tok=='macdef':
                # skip macro lines until blank line
                while idx<len(lines) and lines[idx].strip()!='': idx+=1
                j=len(parts); break
            elif tok=='machine':
                finish(); cur={'login':None,'password':None,'account':None}
                if j+1<len(parts): curkey=parts[j+1]; j+=2
                else: curkey=None; j+=1
            elif tok=='default':
                finish(); cur={'login':None,'password':None,'account':None}; curkey='default'; j+=1
            elif tok in ('login','password','account'):
                if cur is not None and j+1<len(parts): cur[tok]=parts[j+1]; j+=2
                else: j+=1
            else:
                j+=1
    finish()
    return {'entries':entries,'default':default}

def netrc_for_host(host):
    p=find_netrc()
    if not p: return None
    data=parse_netrc(p)
    ent=data['entries'].get((host or '').lower()) or data.get('default')
    if not ent: return None
    if not ent.get('login') or not ent.get('password'): return None
    return ent

@dataclass
class Auth:
    kind: str='basic'  # basic,bearer,digest
    username: str=''
    password: str=''
    token: str=''
    raw: str=''

def prompt_password(scheme, username, host):
    prompt=f"{scheme}: password for {username}@{host}: "
    # rpassword: opens /dev/tty for input/output; prompt printed there.
    try:
        tty_in=open('/dev/tty','rb',buffering=0)
    except OSError as e:
        raise XhError(rust_os_error(e))
    try:
        try: tty_out=open('/dev/tty','wb',buffering=0)
        except: tty_out=None
        if tty_out: tty_out.write(prompt.encode())
        else: sys.stdout.write(prompt); sys.stdout.flush()
        # disable echo if possible
        old=None
        fd=tty_in.fileno()
        try:
            import termios
            old=termios.tcgetattr(fd)
            new=list(old); new[3] &= ~termios.ECHO
            termios.tcsetattr(fd,termios.TCSADRAIN,new)
        except Exception: old=None
        try:
            line=b''
            while True:
                chunk=tty_in.read(1)
                if not chunk: break
                if chunk in (b'\n',b'\r'): break
                if chunk==b'\x03': raise KeyboardInterrupt()
                line+=chunk
        finally:
            if old is not None:
                try:
                    import termios; termios.tcsetattr(fd,termios.TCSADRAIN,old)
                except Exception: pass
            if tty_out: tty_out.write(b'\n')
        return line.decode('utf-8','surrogateescape')
    finally:
        try: tty_in.close()
        except: pass

