    # kind bearer: token=raw
    if kind=='bearer':
        return Auth(kind='bearer',token=raw,raw=raw)
    # split user:pass requiring user at least 1 char before first colon? observed :pass treated as username.
    m=re.match(r'^(.+?):(.*)$', raw, flags=re.DOTALL)
    if m:
        return Auth(kind=kind,username=m.group(1),password=m.group(2),raw=raw)
    # If raw is ':' alone, regex requires .+ before colon fails? But earlier ':' gave Basic ':' without prompt. Special: raw == ':' -> user='', pass=''
    if raw==':':
