    try:
        import email.utils, datetime
        dt=email.utils.parsedate_to_datetime(s)
        if dt is not None:
            if dt.tzinfo is None: dt=dt.replace(tzinfo=datetime.timezone.utc)
            return int(dt.timestamp())
    except Exception: pass
    return None

