def apply_set_cookie(jar, header_val_bytes, url):
    try: s=header_val_bytes.decode('utf-8','surrogateescape')
    except: s=str(header_val_bytes)
    parts=s.split(';')
    if not parts or '=' not in parts[0]: return
    name,val=parts[0].split('=',1); name=name.strip(); val=val.strip()
    if not name: return
    attrs={}
    for p in parts[1:]:
        p=p.strip()
        if not p: continue
        if '=' in p:
            k,v=p.split('=',1); attrs[k.strip().lower()]=v.strip()
        else: attrs[p.lower()]=True
    domain=attrs.get('domain', url.host_connect or '')
    if isinstance(domain,str): domain=domain.lstrip('.')
    path=attrs.get('path') or default_cookie_path(url.path or '/')
    cookie={'name':name,'value':val}
    expires=None; exp_at=None
    if 'expires' in attrs and isinstance(attrs['expires'],str):
        ep=parse_http_date(attrs['expires'])
        if ep is not None: expires=ep; exp_at=ep
    if 'max-age' in attrs:
        try:
            ma=int(attrs['max-age']); exp_at=time.time()+ma
            if ma<=0: exp_at=time.time()-1
        except: pass
    if expires is not None: cookie['expires']=expires
    cookie['path']=path
    if 'secure' in attrs: cookie['secure']=True
    cookie['domain']=domain
    if exp_at is not None: cookie['_expires_at']=exp_at
    # replace same name/domain/path; delete if expired
    for i,c in enumerate(jar):
        if c.get('name')==name and (c.get('domain') or '')==domain and (c.get('path') or '/')==path:
            if exp_at is not None and exp_at<=time.time(): del jar[i]
            else: jar[i]=cookie
            return
    if exp_at is not None and exp_at<=time.time(): return
    jar.append(cookie)

def cookie_header_for(jar,url):
    vals=[]
    for c in jar:
        if cookie_matches(c,url): vals.append(f"{c['name']}={c['value']}")
    return '; '.join(vals) if vals else None

def cookies_for_save(jar):
    out=[]
