@dataclass
class BodyInfo:
    kind: str='none'  # none, bytes, stream_file, stream_multipart
    data: bytes=b''
    file_path: object=None
    multipart_fields: list=field(default_factory=list)
    boundary: str=''
    content_type: object=None
    known_for_print: bool=True  # bytes known to printer for CL
    buffered: object=None

    def get_bytes(self, for_print=False):
        if self.buffered is not None: return self.buffered
        if self.kind=='bytes': return self.data
        if self.kind=='none': return b''
        if self.kind=='stream_file':
            # read file; directories -> error contexts handled by caller
            with open(self.file_path,'rb') as f: b=f.read()
            return b
        if self.kind=='stream_multipart':
            return build_multipart_bytes(self)
        return self.data

def gen_boundary():
    return '-'.join(secrets.token_hex(8) for _ in range(4))

def encode_part_name(name):
    # reqwest multipart: quote if token-ish else RFC5987 name*
    # Determine if name needs encoding: any char not in token or non-ascii or space/quote
    token=set("!#$%&'*+-.^_`|~0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")
    if name and all(c in token for c in name):
        return f'name="{name}"'
    enc=urllib.parse.quote(name, safe="!#$&+-.^_`|~0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")
    return f"name*=utf-8''{enc}"

def quote_filename(fn):
    esc=fn.replace('\\','\\\\').replace('"','\\"')
    return f'filename="{esc}"'

def build_multipart_bytes(body):
    bnd=body.boundary.encode()
    out=bytearray()
    for fld in body.multipart_fields:
        out+=b'--'+bnd+b'\r\n'
        if fld['type']=='text':
            disp=f"Content-Disposition: form-data; {encode_part_name(fld['name'])}"
            out+=disp.encode('utf-8','surrogateescape')+b'\r\n\r\n'
            out+=fld['value'].encode('utf-8','surrogateescape')+b'\r\n'
        else:
            fname=fld['filename']
            disp=f"Content-Disposition: form-data; {encode_part_name(fld['name'])}; {quote_filename(fname)}"
            out+=disp.encode('utf-8','surrogateescape')+b'\r\n'
            if fld.get('mime'):
                out+=f"Content-Type: {fld['mime']}".encode()+b'\r\n'
            out+=b'\r\n'
            with open(fld['path'],'rb') as f: out+=f.read()
            out+=b'\r\n'
    out+=b'--'+bnd+b'--\r\n'
    return bytes(out)

MIME_BY_EXT={'.json':'application/json','.txt':'text/plain','.html':'text/html','.htm':'text/html','.xml':'text/xml','.png':'image/png','.jpg':'image/jpeg','.jpeg':'image/jpeg','.gif':'image/gif','.pdf':'application/pdf','.bin':'application/octet-stream','.dat':'application/octet-stream','.gz':'application/gzip','.zip':'application/zip','.mp4':'video/mp4','.js':'text/javascript','.css':'text/css','.csv':'text/csv'}
def guess_mime(path):
    import mimetypes
    ext=Path(path).suffix.lower()
    if ext in MIME_BY_EXT: return MIME_BY_EXT[ext]
    guess,_=mimetypes.guess_type(path)
    if guess: return guess
    return 'application/json'

