    if for_print:
        if not hm.contains('accept'):
            hm.insert('accept',b'*/*')
        if cookie_val and not hm.contains('cookie'):
            hm.insert('cookie',cookie_val.encode())
        if cl_to_add is not None and body_known:
            hm.insert('content-length',cl_to_add)
        if not hm.contains('host'):
            hm.insert('host',url.host_header().encode())
    else:
        if cl_to_add is not None:
            hm.insert('content-length',cl_to_add)
        if not hm.contains('accept'):
            hm.insert('accept',b'*/*')
        if cookie_val and not hm.contains('cookie'):
            hm.insert('cookie',cookie_val.encode())
        if not hm.contains('host'):
            hm.insert('host',url.host_header().encode())
    return hm

