    i=0;n=len(text)
    def emit(t,c=None):
        if t: out.append(seg(t,c))
    while i<n:
        c=text[i]
        if text.startswith('//',i):
            s=i; i=text.find('\n',i)
            if i==-1: i=n
            emit(text[s:i],fg); continue
        if c in ('"',"'"):
            q=c; s=i; i+=1; cs=i
            while i<n and text[i]!=q:
                if text[i]=='\\': i+=2; continue
                i+=1
            emit(q,th['string']); emit(text[cs:i],th['string'])
            if i<n: emit(q,th['string']); i+=1
            continue
        if c.isdigit():
            s=i
            while i<n and text[i] in '0123456789.eE+-': i+=1
            emit(text[s:i],th['number']); continue
        if c.isalpha() or c in '_$':
            s=i
