def syntax_for_mime(mime):
    if not mime: return None
    m=mime.lower().split(';',1)[0].strip()
    if m=='application/json' or m=='text/json' or m.endswith('+json'): return 'json'
    if m in ('text/html','application/xhtml+xml'): return 'html'
    if m in ('application/xml','text/xml') or m.endswith('+xml'): return 'xml'
    if m in ('text/javascript','application/javascript'): return 'js'
    if m=='text/css': return 'css'
    return None

def colorize_body_text(text,mime,style):
    lang=syntax_for_mime(mime)
    if lang is None: return text
    # syntect processes line by line; preserve newlines outside highlighted segments roughly
    lines=text.split('\n')
    rendered=[]
    for line in lines:
        if lang=='json': rendered.append(tokenize_json_color(line,style).rstrip()) # tokenize adds reset; keep? need strip spaces not codes
        elif lang in ('html','xml'): rendered.append(tokenize_markup_color(line,style))
        else: rendered.append(tokenize_generic_color(line,style,lang))
    # Tokenizers append a final \x1b[0m per line; syntect would too on each line segment. Join with newline.
    return '\n'.join(rendered)

