    return data

def _decompress_brotli(data):
    try:
        import brotli; return brotli.decompress(data)
    except ImportError:
        pass
    # ctypes libbrotlidec if present
    import ctypes, ctypes.util
    libname=ctypes.util.find_library('brotlidec')
    if not libname: raise Exception('brotli not available')
    lib=ctypes.CDLL(libname)
    # Use stream API is complex; use one-shot BrotliDecoderDecompress(encoded_size, encoded, decoded_size*, decoded)
    out_size=ctypes.c_size_t(max(len(data)*10, 1024))
    # Try grow up to large
    for factor in (10,100,1000):
        out_size=ctypes.c_size_t(max(len(data)*factor,1024))
        outbuf=ctypes.create_string_buffer(out_size.value)
        res=lib.BrotliDecoderDecompress(ctypes.c_size_t(len(data)), data, ctypes.byref(out_size), outbuf)
        if res==1: return outbuf.raw[:out_size.value]
    raise Exception('brotli decompress failed')

def _decompress_zstd(data):
    try:
        import zstandard; return zstandard.ZstdDecompressor().decompress(data)
    except ImportError:
        pass
    import ctypes, ctypes.util
    libname=ctypes.util.find_library('zstd')
    if not libname: raise Exception('zstd not available')
    lib=ctypes.CDLL(libname)
    bound=lib.ZSTD_getFrameContentSize(data, len(data))
    if bound in (18446744073709551615,18446744073709551614) or bound<0:
        bound=max(len(data)*10,1024)
    outbuf=ctypes.create_string_buffer(int(bound))
    res=lib.ZSTD_decompress(outbuf, ctypes.c_size_t(int(bound)), data, ctypes.c_size_t(len(data)))
    if lib.ZSTD_isError(ctypes.c_size_t(res)):
        raise Exception('zstd decompress failed')
    return outbuf.raw[:res]

