def parse_digest_challenge(value_str):
    # value_str is full header value string
    s=value_str.strip()
    # crate expects after "Digest" maybe; errors include original challenge remainder as given
    # Remove scheme token if present case-insensitive
    original_for_error=value_str
    rest=s
    if rest.lower().startswith('digest'):
        # Keep remainder including leading space for error wording: Missing "realm" in header:  nonce=...
        rest=s[6:]
        orig_remainder=rest
    else:
        # observed for Basic: Missing "realm" in header: Basic realm=...
        orig_remainder=value_str
        rest=s
    params={}
    for part in re.finditer(r'([A-Za-z0-9_\-]+)\s*=\s*(?:"((?:\\.|[^"\\])*)"|([^,]*))',rest):
        k=part.group(1).lower(); v=part.group(2) if part.group(2) is not None else (part.group(3).strip() if part.group(3) else '')
        if part.group(2) is not None: v=v.replace('\\"', '"').replace('\\\\','\\')
        params[k]=v
    if 'realm' not in params:
        raise XhError(f'Missing "realm" in header: {orig_remainder if rest!=value_str else value_str}')
    if 'nonce' not in params:
        raise XhError(f'Missing "nonce" in header: {orig_remainder if rest!=value_str else value_str}')
    alg=params.get('algorithm','MD5')
    if alg not in ('MD5','MD5-sess','SHA-256','SHA-256-sess','SHA-512-256','SHA-512-256-sess'):
        raise XhError(f'Unknown algorithm: {alg}')
    qop_raw=params.get('qop')
    qop=None
