def digest_hash(alg,data_str):
    b=data_str.encode('utf-8','surrogateescape')
    if alg.startswith('MD5'): return hashlib.md5(b).hexdigest()
    if alg.startswith('SHA-256'): return hashlib.sha256(b).hexdigest()
